entries[84122] = { ["name"] = "Rezept: Fläschchen des Alchemisten", ["text"] = "Benötigt Alchemie\n(550)\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens des Alchemisten\n\nFläschchen des Alchemisten\nWird beim Aufheben gebunden\nBenötigt Alchemie\n(300)\nBenutzen: Erhöht Eure Beweglichkeit, Stärke oder Intelligenz 2 Stunden lang um 320 . Es wird stets Euer höchster Wert gewählt.\n\nGilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\"Kann in Arenen verwendet werden. Dieses mächtige Fläschchen wird bei der Verwendung nicht verbraucht, profitiert jedoch nicht von Mixologie.\"\nBenötigt Kristallphiole , Eiskappe (7), Bergsilbersalbei (7), Geisterpilz (7)" }
entries[84123] = { ["name"] = "Rezept: Fläschchen der Herbstblätter", ["text"] = "Benötigt Alchemie\n(550)\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der Herbstblätter.\nBeim Herstellen dieses Fläschchens besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nFläschchen der Herbstblätter\nBenötigt Stufe 85\nBenutzen: Erhöht die Willenskraft 1 Stunde lang um 1000 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Teepflanze (4), Goldlotus" }
entries[84124] = { ["name"] = "Rezept: Meisterlicher Heiltrank", ["text"] = "Benötigt Alchemie\n(500)\nBenutzen: Lehrt Euch die Herstellung eines meisterlichen Heiltranks.\nBeim Herstellen dieses Gegenstands besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nMeisterlicher Heiltrank\nBenötigt Stufe 85\nBenutzen: Stellt 120000 Gesundheit wieder her. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Teepflanze" }
entries[84125] = { ["name"] = "Rezept: Goldberyll transmutieren", ["text"] = "Benötigt Alchemie\n(575)\nBenutzen: Lehrt Euch die Transmutation eines Goldberylls.\nBeim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nGoldberyll\nVerkaufspreis:\nBenötigt Sonnenstein , Goldlotus" }
entries[84126] = { ["name"] = "Rezept: Aragonit transmutieren", ["text"] = "Benötigt Alchemie\n(575)\nBenutzen: Lehrt Euch die Transmutation eines Aragoniten.\nBeim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nAragonit\nVerkaufspreis:\nBenötigt Chiastolith , Goldlotus" }
entries[84127] = { ["name"] = "Rezept: Verjüngung des Alchemisten", ["text"] = "Benötigt Alchemie\n(500)\nBenutzen: Lehrt Euch die Herstellung einer Verjüngung des Alchemisten\nBeim Herstellen dieses Tranks besteht eine Chance, dass Ihr andere Alchemierezepte aus Pandaria entdeckt.\n\nAuf diese Weise entdeckte Rezepte können weitere Rezepte enthüllen, wenn Ihr mit ihnen Gegenstände herstellt.\n\nVerjüngung des Alchemisten\nBenötigt Stufe 85\nBenötigt Alchemie\n(500)\nBenutzen: Stellt 120000 Gesundheit und 1 Mana wieder her. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Teepflanze" }
