entries[84579] = { ["name"] = "Formel: Waffe - Koloss", ["text"] = "Benötigt Verzauberkunst (575)\nBenutzen: Lehrt Euch7500 Nahkampfwaffen dauerhaft zu verzaubern7500 sodass Eure Schaden verursachenden Nahkampftreffer manchmal einen Schutzzauber der Mogu aktivieren7500 der Schaden absorbiert. Erfordert einen Gegenstand der Stufe 7500 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal einen Schutzzauber der Mogu auslösen, der bis zu 7500 erlittenen Schaden absorbiert." }
entries[84580] = { ["name"] = "Formel: Waffe - Flussgesang", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (600)\nBenötigt Shado-Pan\n- Respektvoll\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass manchmal Euer Ausweichen erhöht wird, wenn Ihr Nahkampfschaden verursacht. Erfordert einen Gegenstand der Stufe 372 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Euer Ausweichen 7 Sek. lang um 1650 erhöhen.\nVerkaufspreis:" }
entries[84581] = { ["name"] = "Formel: Waffe - Elementarkraft", ["text"] = "Benötigt Verzauberkunst (525)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass manchmal zusätzlicher Schaden verursacht wird, wenn mit Zaubern und Nahkampfangriffen Schaden verursacht wird. Erfordert einen Gegenstand der Stufe 372 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe und Zauber manchmal zusätzliche 3000 Elementarschaden verursachen." }
entries[84582] = { ["name"] = "Formel: Waffe - Windweise", ["text"] = "Benötigt Verzauberkunst (550)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass verursachter Zauber- und Nahkampfschaden den kritischen Trefferwert, das Tempo oder die Meisterschaft manchmal 12 Sek. lang um 1.500 erhöht. Erfordert einen Gegenstand der Stufe 372 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilzauber, Schadenszauber und Schaden verursachenden Nahkampfangriffe manchmal Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert 12 Sek. lang um 1500 erhöhen." }
entries[84583] = { ["name"] = "Formel: Waffe - Jadegeist", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (600)\nBenötigt Shado-Pan\n- Respektvoll\nBenutzen: Lehrt Euch1650 Nahkampfwaffen dauerhaft zu verzaubern1650 sodass hervorgerufene Heilung oder verursachter Zauberschaden manchmal Eure Intelligenz erhöhen. Erhöht bei niedrigem Mana außerdem Eure Willenskraft. Erfordert einen Gegenstand der Stufe 1650 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 1650 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Willenskraft ebenfalls um 0 erhöht.\nVerkaufspreis:" }
entries[84584] = { ["name"] = "Formel: Waffe - Tanzender Stahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (600)\nBenötigt Shado-Pan\n- Respektvoll\nBenutzen: Lehrt Euch1650 Nahkampfwaffen dauerhaft zu verzaubern1650 sodass Eure Stärke oder Beweglickeit manchmal um 1650.1650 erhöht wird1650 wenn Ihr Nahkampfschaden verursacht. Erfordert einen Gegenstand der Stufe 1650 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Eure Stärke oder Beweglichkeit um 1650 erhöhen. Der höhere der beiden Werte wird gewählt.\nVerkaufspreis:" }
