entries[84727] = { ["name"] = "Uralter Seelenstaub", ["text"] = "Questgegenstand\n\"Überreste eines uralten Yaungolgeistes. Bringt vier dieser Überreste zu einem uralten Leichnam, um den Geist zu befreien und ihn in sein nächstes Leben zu entlassen.\"" }
entries[84728] = { ["name"] = "Zügel des Scharlachroten Reitkranichs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren scharlachroten Reitkranich und entlässt ihn wieder.\nVerkaufspreis:" }
entries[84753] = { ["name"] = "Zügel des weißen Reityaks", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 85\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares weißes Reityak und entlässt es wieder.\nVerkaufspreis:" }
