entries[84830] = { ["name"] = "Lederhandschuhe des bösartigen Gladiators", ["text"] = "Saison 12\nWird beim Aufheben gebunden\nHände Leder\n1738 Rüstung\n+725 Beweglichkeit\n+1.208 Ausdauer\nErhöht Eure Trefferwertung um + 457.\nErhöht Eure kritische Trefferwertung um + 537.\nErhöht Eure PvP-Macht um + 322.\n\nBlauer Sockel\nSockelbonus: + 60 Beweglichkeit\n\nHaltbarkeit 60 / 60\nKlassen: Schurke\nBenötigt Stufe 90\nAnlegen: Erhöht Eure durch 'Gesundung' erhaltene Heilung alle 3 Sek. um 1%.\n\nGewänder des Gladiators (0/5)\nLedertunika des Gladiators\nLederhandschuhe des Gladiators\nLederhelm des Gladiators\nLederbeinschützer des Gladiators\nLederschiftung des Gladiators\n(2) Set : Erhöht die PvP-Macht um 500.\n(2) Set : Wenn Ihr ein Ziel mit einem Eurer nicht-tödlichen Gifte vergiftet, vergiftet Ihr das Ziel auch mit verkrüppelndem Gift.\n(4) Set : Erhöht Eure maximale Energie um 30.\n(4) Set : Erhöht die PvP-Macht um 1000.\nVerkaufspreis:" }
entries[84831] = { ["name"] = "Zierrathandschuhe des bösartigen Gladiators", ["text"] = "Saison 12\nWird beim Aufheben gebunden\nHände Platte\n3302 Rüstung\n+1.208 Ausdauer\n+725 Intelligenz\n+457 Willenskraft\nErhöht Eure Tempowertung um + 537.\nErhöht Eure PvP-Macht um + 322.\n\nBlauer Sockel\nSockelbonus: + 60 Intelligenz\n\nHaltbarkeit 60 / 60\nKlassen: Paladin\nBenötigt Stufe 90\nAnlegen: Erhöht die Chance auf einen kritischen Treffer mit Eurem Zauber 'Lichtblitz' um 2%.\n\nErlösung des Gladiators (0/5)\nZierratbrustschutz des Gladiators\nZierrathandschuhe des Gladiators\nZierratkopfbedeckung des Gladiators\nZierratbeinplatten des Gladiators\nZierratschiftung des Gladiators\n(2) Set : Erhöht den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 10%.\n(2) Set : Erhöht die PvP-Macht um 500.\n(4) Set : Erhöht die PvP-Macht um 1000.\n(4) Set : Wenn Ihr 'Lichtblitz' wirkt, erhaltet Ihr 1 heilige Kraft.\nVerkaufspreis:" }
entries[84832] = { ["name"] = "Drachenlederhandschuhe des bösartigen Gladiators", ["text"] = "Saison 12\nWird beim Aufheben gebunden\nHände Leder\n1738 Rüstung\n+725 Beweglichkeit\n+1.208 Ausdauer\nErhöht Eure Trefferwertung um + 457.\nErhöht Eure kritische Trefferwertung um + 537.\nErhöht Eure PvP-Macht um + 322.\n\nBlauer Sockel\nSockelbonus: + 60 Beweglichkeit\n\nHaltbarkeit 60 / 60\nKlassen: Druide\nBenötigt Stufe 90\nAnlegen: Erhöht den Schaden von 'Zerfleddern' um 100% und erhöht die Effektdauer von 'Klammergriff' um 1 Sek.\n\nSchutzgewandung des Gladiators (0/5)\nDrachenlederhandschuhe des Gladiators\nDrachenlederhelm des Gladiators\nDrachenlederbeinschützer des Gladiators\nDrachenlederroben des Gladiators\nDrachenlederschiftung des Gladiators\n(2) Set : Erhöht die PvP-Macht um 500.\n(2) Set : Erhöht Euer Bewegungstempo in Bären-, Katzen- oder Reisegestalt um 15%. Kann nur im Freien verwendet werden. Diese Geschwindigkeitserhöhung ist nicht kumulativ mit 'Schnelligkeit der Wildnis'.\n(4) Set : Erhöht die PvP-Macht um 1000.\n(4) Set : Einmal alle 30 Sek. ist der Einsatz von 'Verheeren' kostenlos und benötigt weder Verstohlenheit noch spezielle Positionierung. Zusätzlich wird, wenn Ihr mit 'Schädelstoß' erfolgreich einen Zauber unterbrecht, die Abklingzeit von 'Wutanfall' abgeschlossen.\nVerkaufspreis:" }
